# Deathmark (FDN): "Destroy target green or white creature."
# Liliana's Scorn's DESTROY TARGET creature, the colour "green or white" an FOr of COLOR_HAS
# (MAPPER_GUIDE: never COLOR_IN, a subset test).
abilities = [
    SpellAbility(
        kind=SpellKind.SORCERY,
        effect=A(Verb.DESTROY, {
            'target': Selector(
                count=QConst(value=1),
                mode=SelectorMode.TARGET,
                filter=FAnd(
                    children=(
                        FOr(
                            children=(
                                FAtom(pred=FAtomPred.COLOR_HAS, color='G'),
                                FAtom(pred=FAtomPred.COLOR_HAS, color='W'),
                            ),
                        ),
                        FAtom(pred=FAtomPred.TYPE_EQ, string_value='Creature'),
                    ),
                ),
                zones=(Zone(kind=ZoneKind.BATTLEFIELD, controller=ControllerRef.ANY),),
            ),
        }),
    ),
]
